window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5df6f6d7c2fa731e"]={"versions": [{"id": "FIG-5df6f6d7c2fa731e", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Beschreibung der Hardware-Ressourcen eines Steuergeräts (AUTOSAR Resource Template ECU). Das Diagramm modelliert die strukturelle Zusammensetzung und Hardware-Eigenschaften eines Kommunikations-Transceivers (<code>CommunicationTransceiver</code>) sowie dessen Anbindung an Ports, Filter, physikalische Medien und Busabschlüsse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\"><li><strong>CommunicationTransceiver</strong> (Spezialisierung von <em>ECUElectronics</em>):\n<ul class=\"fig-list\"><li>Attribut: <code>+ architecture: Enumeration{master, slave, multiMaster} [0..1]</code>\n</li><li>Komposition <code>+termination [0..1]</code> zu <strong>BusTermination</strong>\n</li><li>Kompositionen zu <strong>CommunicationFilter</strong> in zwei Rollen:\n<ul class=\"fig-list\"><li><code>+ACCEPTANCE-FILTER [0..1]</code>\n</li><li><code>+REJECTION-FILTER [0..1]</code>\n</li></ul>\n</li><li>Gerichtete Abhängigkeit / Referenz <code>wakeupInterrupt</code> zu <strong>InterruptProduceHWPort</strong>\n</li><li>Gerichtete Abhängigkeit / Referenz <code>communicationHWPort</code> zu <strong>CommunicationHWPort</strong>\n</li></ul>\n</li><li><strong>BusTermination</strong>:\n<ul class=\"fig-list\"><li>Attribute: <code>+ value: Int [0..1]</code>, <code>+ split: Boolean [0..1]</code>, <code>+ activeSwitchable: Boolean [0..1]</code>, <code>+ choke: Boolean [0..1]</code>, <code>+ emcFilter: Boolean [0..1]</code>\n</li></ul>\n</li><li><strong>CommunicationFilter</strong>:\n<ul class=\"fig-list\"><li>Attribute: <code>+ filterCount: Int</code>, <code>+ filterWidth: Int</code>, <code>+ wildCards: Boolean [0..1]</code>\n</li></ul>\n</li><li><strong>InterruptProduceHWPort</strong> (Spezialisierung von <em>InterruptHWPort</em>):\n<ul class=\"fig-list\"><li>Ziel der Wakeup-Interrupt-Abhängigkeit des Transceivers.\n</li></ul>\n</li><li><strong>CommunicationHWPort</strong> (Spezialisierung von <em>PeripheralHWPort</em>):\n<ul class=\"fig-list\"><li>Komposition <code>+physicalLayer [0..1]</code> zu <strong>CommunicationPhysicalMedium</strong>\n</li><li>Komposition <code>+speed [1]</code> zu der abstrakten Basisklasse <strong>CommunicationSpeed</strong>\n</li></ul>\n</li><li><strong>CommunicationPhysicalMedium</strong>:\n<ul class=\"fig-list\"><li>Attribute: <code>+ physicalMediumType: Enumeration{ELECTRICAL, OPTICAL, WIRELESS} [0..1]</code>, <code>+ physicalMediumStandard: String [0..1]</code>, <code>+ physicalMediumDataLines: Int [0..1]</code>\n</li></ul>\n</li><li><strong>CommunicationSpeed</strong> (abstrakt):\n<ul class=\"fig-list\"><li>Attribut: <code>+ tolerance: Float [0..1]</code>\n</li><li>Generalisierungsklassen:\n<ul class=\"fig-list\"><li><strong>CommunicationSpeedFixed</strong>: Attribut <code>+ fixSpeed: Int</code>\n</li><li><strong>CommunicationSpeedRange</strong>: Attribute <code>+ minSpeed: Int</code>, <code>+ maxSpeed: Int</code>\n</li><li><strong>CommunicationSpeedList</strong>: Attribut <code>+ speed: Int [1..*]</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Verhaltens- oder Ablaufsemantik. Das Diagramm spezifiziert deklarative Hardware-Beschreibungsstrukturen für Transceiver-Konfigurationen und Portzuweisungen zur Entwurfs- bzw. Beschreibungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Datenmodell für AUTOSAR ECU Resource Descriptions. Es definiert verbindliche Metaklassen, Rollennamen, Multiplizitäten und Attributtypen zur herstellerunabhängigen Beschreibung von Transceiver-Hardwarekomponenten. Implementierungen von ECU-Ressourcentemplates müssen die Kardinalitäten (z. B. genau eine <code>CommunicationSpeed</code>-Instanz pro <code>CommunicationHWPort</code>, optionale Filter und Busabschlüsse) sowie die Vererbungshierarchien der Spezifikationsklassen einhalten.</p>"}, {"id": "FIG-9254e0250c070e27", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Beschreibung der Hardware-Ressourcen eines Steuergeräts (AUTOSAR Resource Template ECU). Das Diagramm modelliert die strukturelle Zusammensetzung und Hardware-Eigenschaften eines Kommunikations-Transceivers (<code>CommunicationTransceiver</code>) sowie dessen Anbindung an Ports, Filter, physikalische Medien und Busabschlüsse.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert folgende Entitäten, Attribute und Assoziationen:</p>\n<ul class=\"fig-list\"><li><strong>CommunicationTransceiver</strong> (Spezialisierung von <em>ECUElectronics</em>):\n<ul class=\"fig-list\"><li>Attribut: <code>+ architecture: Enumeration{master, slave, multiMaster} [0..1]</code>\n</li><li>Komposition <code>+termination [0..1]</code> zu <strong>BusTermination</strong>\n</li><li>Kompositionen zu <strong>CommunicationFilter</strong> in zwei Rollen:\n<ul class=\"fig-list\"><li><code>+ACCEPTANCE-FILTER [0..1]</code>\n</li><li><code>+REJECTION-FILTER [0..1]</code>\n</li></ul>\n</li><li>Gerichtete Abhängigkeit / Referenz <code>wakeupInterrupt</code> zu <strong>InterruptProduceHWPort</strong>\n</li><li>Gerichtete Abhängigkeit / Referenz <code>communicationHWPort</code> zu <strong>CommunicationHWPort</strong>\n</li></ul>\n</li><li><strong>BusTermination</strong>:\n<ul class=\"fig-list\"><li>Attribute: <code>+ value: Int [0..1]</code>, <code>+ split: Boolean [0..1]</code>, <code>+ activeSwitchable: Boolean [0..1]</code>, <code>+ choke: Boolean [0..1]</code>, <code>+ emcFilter: Boolean [0..1]</code>\n</li></ul>\n</li><li><strong>CommunicationFilter</strong>:\n<ul class=\"fig-list\"><li>Attribute: <code>+ filterCount: Int</code>, <code>+ filterWidth: Int</code>, <code>+ wildCards: Boolean [0..1]</code>\n</li></ul>\n</li><li><strong>InterruptProduceHWPort</strong> (Spezialisierung von <em>InterruptHWPort</em>):\n<ul class=\"fig-list\"><li>Ziel der Wakeup-Interrupt-Abhängigkeit des Transceivers.\n</li></ul>\n</li><li><strong>CommunicationHWPort</strong> (Spezialisierung von <em>PeripheralHWPort</em>):\n<ul class=\"fig-list\"><li>Komposition <code>+physicalLayer [0..1]</code> zu <strong>CommunicationPhysicalMedium</strong>\n</li><li>Komposition <code>+speed [1]</code> zu der abstrakten Basisklasse <strong>CommunicationSpeed</strong>\n</li></ul>\n</li><li><strong>CommunicationPhysicalMedium</strong>:\n<ul class=\"fig-list\"><li>Attribute: <code>+ physicalMediumType: Enumeration{ELECTRICAL, OPTICAL, WIRELESS} [0..1]</code>, <code>+ physicalMediumStandard: String [0..1]</code>, <code>+ physicalMediumDataLines: Int [0..1]</code>\n</li></ul>\n</li><li><strong>CommunicationSpeed</strong> (abstrakt):\n<ul class=\"fig-list\"><li>Attribut: <code>+ tolerance: Float [0..1]</code>\n</li><li>Generalisierungsklassen:\n<ul class=\"fig-list\"><li><strong>CommunicationSpeedFixed</strong>: Attribut <code>+ fixSpeed: Int</code>\n</li><li><strong>CommunicationSpeedRange</strong>: Attribute <code>+ minSpeed: Int</code>, <code>+ maxSpeed: Int</code>\n</li><li><strong>CommunicationSpeedList</strong>: Attribut <code>+ speed: Int [1..*]</code>\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Verhaltens- oder Ablaufsemantik. Das Diagramm spezifiziert deklarative Hardware-Beschreibungsstrukturen für Transceiver-Konfigurationen und Portzuweisungen zur Entwurfs- bzw. Beschreibungszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Datenmodell für AUTOSAR ECU Resource Descriptions. Es definiert verbindliche Metaklassen, Rollennamen, Multiplizitäten und Attributtypen zur herstellerunabhängigen Beschreibung von Transceiver-Hardwarekomponenten. Implementierungen von ECU-Ressourcentemplates müssen die Kardinalitäten (z. B. genau eine <code>CommunicationSpeed</code>-Instanz pro <code>CommunicationHWPort</code>, optionale Filter und Busabschlüsse) sowie die Vererbungshierarchien der Spezifikationsklassen einhalten.</p>"}], "trans": [{"from": "FIG-5df6f6d7c2fa731e", "to": "FIG-9254e0250c070e27", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
